export const membraneLesson="<div class=\"lesson-kicker\">01 / THE MEMBRANE</div><h2>A tiny separation.<br>A real voltage.</h2><p class=\"lesson-intro\">A thin membrane separates two conductive fluids. A <b>small excess of charge on its surfaces</b> creates a voltage across it.<br><br>Open an ion channel, and charged ions move. That changes the separation—and the membrane voltage.</p><div class=\"formula-card\"><div class=\"formula-label\">MEASURE INSIDE MINUS OUTSIDE</div><div class=\"formula\">V<sub>m</sub> = φ<sub>i</sub> − φ<sub>e</sub></div><div class=\"formula-desc\">One probe inside the cell. One just outside.</div></div><div class=\"now-card\"><div class=\"now-label\"><i></i><span id=\"now-title\"></span></div><p class=\"now-copy\" id=\"now-copy\"></p></div><div class=\"control-block\"><div class=\"control-label\">EXPLORE THE ACTION POTENTIAL</div><div class=\"phase-buttons\"><button class=\"phase-btn\" data-phase=\"0\"><b>−</b>Rest</button><button class=\"phase-btn\" data-phase=\"1\"><b>Na⁺ ↓</b>Depolarize</button><button class=\"phase-btn\" data-phase=\"2\"><b>⇅</b>Plateau</button><button class=\"phase-btn\" data-phase=\"3\"><b>K⁺ ↑</b>Recover</button></div><label class=\"toggle-row\">Show ions in the surrounding fluid<input type=\"checkbox\" class=\"toggle\" id=\"ions-toggle\" checked></label><label class=\"toggle-row\">Highlight excess membrane charge<input type=\"checkbox\" class=\"toggle\" id=\"charges-toggle\" checked></label><p class=\"experiment-hint\"><span>↳</span>Both bulk fluids remain nearly neutral. The surface charge is greatly exaggerated.</p></div>";
export const leadLesson="<div class=\"lesson-kicker\">03 / THE LEAD</div><h2>Two places.<br>One difference.</h2><p class=\"lesson-intro\">Tissue currents set up a pattern of extracellular potential. Two electrodes sample that pattern.<br><br>The EKG records <b>positive input minus negative input</b>. Rotate the pair or swap the inputs to see what changes.</p><div class=\"formula-card\"><div class=\"formula-label\">THE VOLTAGE MEASURED BY THE LEAD</div><div class=\"formula\">V = φ<sub>+</sub> − φ<sub>−</sub></div><div class=\"reading-row\"><div class=\"reading\"><span>φ₊</span><strong id=\"phi-plus\">+0.00</strong><small>mV</small></div><div class=\"reading\"><span>φ₋</span><strong id=\"phi-minus\">+0.00</strong><small>mV</small></div><div class=\"reading\"><span>Difference</span><strong id=\"phi-diff\">0.00</strong><small>mV</small></div></div></div><div class=\"now-card\"><div class=\"now-label\"><i></i><span id=\"now-title\"></span></div><p class=\"now-copy\" id=\"now-copy\"></p></div><div class=\"control-block\"><label for=\"angle\" class=\"control-label\">ROTATE THE LEAD <strong id=\"angle-value\">0°</strong></label><div class=\"angle-range\"><input id=\"angle\" type=\"range\" min=\"0\" max=\"180\" step=\"1\" value=\"0\"></div><div class=\"angle-presets\"><button data-angle=\"0\">Aligned · 0°</button><button data-angle=\"90\">Across · 90°</button><button data-angle=\"180\">Opposite · 180°</button></div><div class=\"secondary-controls\"><button class=\"experiment-button\" id=\"swap\">Swap + / −</button><button class=\"experiment-button\" id=\"offset\">Both inputs +2 mV</button></div><label class=\"toggle-row\">Show extracellular potential<input type=\"checkbox\" class=\"toggle\" id=\"field-toggle\" checked></label><p class=\"experiment-hint\"><span>↳</span>The same offset at both inputs cancels. A negative reading just means φ₊ is lower.</p></div>";
